def solution() -> int:
    Return the minimum possible absolute difference between the sums of two partitions.
    Uses a classic subset‑sum dynamic programming approach.

    weights = [20, 26, 11, 11, 15, 1, 13, 15]
    total = sum(weights)
    target = total // 2

    # dp[i] = True if a subset sum of i is achievable
    dp = [False] * (target + 1)
    dp[0] = True

    for w in weights:
        # iterate backwards to avoid reusing the same element
        for s in range(target, w - 1, -1):
            if dp[s - w]:
                dp[s] = True

    # find the largest achievable sum <= target
    for s in range(target, -1, -1):
        if dp[s]:
            best = s
            break

    other = total - best
    return abs(other - best)

