from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Define the undirected graph as an adjacency list
    graph = {
        0: [(2, 6), (3, 3)],
        1: [(2, 5), (3, 2)],
        2: [(0, 6), (1, 5), (3, 3)],
        3: [(0, 3), (1, 2), (2, 3)],
    }

    start, target = 0, 3

    # Dijkstra's algorithm
    heap = [(0, start, [])]  # (cumulative distance, current node, path so far)
    visited = set()
    while heap:
        dist, node, path = heapq.heappop(heap)
        if node in visited:
            continue
        visited.add(node)
        path = path + [node]
        if node == target:
            return (path, dist)
        for neighbor, weight in graph.get(node, []):
            if neighbor not in visited:
                heapq.heappush(heap, (dist + weight, neighbor, path))
    # If no path found, return empty results
    return ([], float('inf'))

