import itertools
from typing import List, Tuple

def solution() -> Tuple[bool, int, List[int]]:
    weights = [2, 1, 3, 3]
    values = [4, 2, 1, 4]
    capacity = 20
    n = len(weights)
    best_val = 0
    best_set: List[int] = []
    for r in range(n + 1):
        for combo in itertools.combinations(range(n), r):
            total_w = sum(weights[i] for i in combo)
            if total_w <= capacity:
                total_v = sum(values[i] for i in combo)
                if total_v > best_val:
                    best_val = total_v
                    best_set = list(combo)
    feasible = best_val > 0 or capacity >= 0
    return (feasible, best_val, best_set)

