import collections

def solution() -> dict:
    Return a 2‑coloring of the given graph.
    The graph has vertices 1‑6 and edges:
        (1,3), (1,4), (2,3), (3,6), (4,5)

    # define edges
    edges = [(1, 3), (1, 4), (2, 3), (3, 6), (4, 5)]

    # build adjacency list
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS two‑coloring (colors 'A' and 'B')
    color = {}
    for start in range(1, 7):
        if start not in color:
            queue = collections.deque([start])
            color[start] = 'A'
            while queue:
                u = queue.popleft()
                for w in adj[u]:
                    if w not in color:
                        color[w] = 'B' if color[u] == 'A' else 'A'
                        queue.append(w)
                    elif color[w] == color[u]:
                        raise ValueError('Graph is not 2‑colorable')
    return color

